function text(value, fallback = "") {
  const result = String(value ?? "").trim();
  return result || fallback;
}

function escapeHtml(value) {
  return text(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function list(items, fallback = "暂无") {
  const values = Array.isArray(items) ? items.filter(Boolean) : [];
  return values.length ? values : [fallback];
}

function analysisOf(result = {}) {
  return result.danmakuAnalysis && typeof result.danmakuAnalysis === "object" ? result.danmakuAnalysis : result;
}

function metric(value) {
  return Number.isFinite(Number(value)) ? Number(value).toLocaleString("zh-CN") : "0";
}

function numeric(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function percentage(value, total) {
  const base = numeric(total);
  if (!base) return 0;
  return Math.max(0, Math.min(100, Math.round((numeric(value) / base) * 100)));
}

function firstPerson(value, prefix = "我建议") {
  const result = text(value);
  if (!result) return prefix;
  return /^我(?:建议|看到|会|已经)/.test(result) ? result : `${prefix}${result}`;
}

function optimizationOf(analysis = {}) {
  const source = analysis.optimization && typeof analysis.optimization === "object" ? analysis.optimization : {};
  return {
    headline: text(source.headline, "下一场继续围绕用户反复提问的主题优化讲解顺序。"),
    priorityTopics: Array.isArray(source.priorityTopics) ? source.priorityTopics : [],
    nextLiveActions: Array.isArray(source.nextLiveActions) ? source.nextLiveActions : []
  };
}

function buildLegacyLiveDanmakuAnalysisReportHtml(result = {}) {
  const analysis = analysisOf(result);
  const counts = analysis.counts || {};
  const topics = Array.isArray(analysis.topics) ? analysis.topics : [];
  const optimization = optimizationOf(analysis);
  const userStats = analysis.userStats || {};
  const totalDanmaku = numeric(counts.danmaku ?? counts.total);
  const uniqueUsers = numeric(counts.uniqueUsers);
  const maxTopicCount = Math.max(1, ...topics.map((topic) => numeric(topic.count)));
  const questionRate = percentage(counts.questions, totalDanmaku);
  const repeatRate = percentage(userStats.repeatUsers, uniqueUsers);
  const topicSections = topics.length
    ? topics.map(topic => `<li><strong>${escapeHtml(text(topic.label || topic.name, "未命名主题"))}</strong> · ${escapeHtml(metric(topic.count))} 条 · ${escapeHtml(metric(topic.userCount))} 位用户${topic.examples?.length ? `：${escapeHtml(topic.examples.join("；"))}` : ""}</li>`).join("")
    : '<li>暂无高频主题</li>';
  const topicChart = topics.length
    ? topics.map((topic, index) => {
      const count = numeric(topic.count);
      const width = Math.max(8, Math.round((count / maxTopicCount) * 100));
      return `<div class="topic-row"><div class="topic-row-head"><strong><b>${String(index + 1).padStart(2, "0")}</b>${escapeHtml(text(topic.label || topic.name, "未命名主题"))}</strong><span>${escapeHtml(metric(count))} 条 · ${escapeHtml(metric(topic.userCount))} 位用户</span></div><div class="topic-track"><i style="width:${width}%"></i></div><p>${escapeHtml(text(topic.examples?.[0], "暂无代表性原话"))}</p></div>`;
    }).join("")
    : '<p class="empty">本场没有形成稳定主题。</p>';
  const priorityTopics = optimization.priorityTopics.length
    ? optimization.priorityTopics.map((topic) => `<article class="priority"><h3>${escapeHtml(text(topic.label, "待命名主题"))}<span>${escapeHtml(text(topic.priority, "观察"))}</span></h3><p class="meta">${escapeHtml(metric(topic.count))} 条弹幕 · ${escapeHtml(metric(topic.userCount))} 位用户</p><p>${escapeHtml(text(topic.observation, "用户在该主题持续表达关注。"))}</p><p><strong>建议动作：</strong>${escapeHtml(text(topic.strategy, "把该主题安排到商品讲解的固定环节。"))}</p>${topic.examples?.length ? `<ul>${topic.examples.map(item => `<li>“${escapeHtml(item)}”</li>`).join("")}</ul>` : ""}</article>`).join("")
    : '<p class="empty">本场没有形成稳定主题，下一场先补齐商品、价格和使用场景说明。</p>';
  const nextLiveActions = list(optimization.nextLiveActions).map((action) => `<li>${escapeHtml(action)}</li>`).join("");
  const evidence = list((analysis.evidence || []).map(item => item?.quote).filter(Boolean), "本场没有返回可展示的原始弹幕").slice(-30).map(item => `<li>“${escapeHtml(item)}”</li>`).join("");
  const source = analysis.analysisSource === "ai" ? "AI + 规则归纳" : "规则归纳";
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>直播间弹幕分析报告</title><style>body{margin:0;background:#f5f7fa;color:#26313d;font:16px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}.page{max-width:900px;margin:0 auto;padding:48px 28px}.cover,.section{background:#fff;border:1px solid #e0e6ed;border-radius:12px;padding:28px;margin-bottom:20px}.cover{border-top:4px solid #3182f6}.eyebrow{color:#718096;font-size:13px;letter-spacing:.08em}.meta,.muted{color:#718096}.summary{font-size:18px}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.metric{background:#f4f7fb;border-radius:8px;padding:14px}.metric strong{display:block;font-size:24px}.metric span{color:#718096;font-size:13px}.priority{border-top:1px solid #e8edf2;padding:18px 0}.priority:first-child{border-top:0}.priority h3{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0;color:#26313d;font-size:17px}.priority h3 span{color:#3182f6;font-size:12px}.priority p{margin:7px 0 0}.priority strong{color:#26313d}.empty{color:#8b97a3}.action-list{margin:10px 0 0;padding-left:20px}.evidence-list{margin:0;padding-left:20px}@media(max-width:700px){.page{padding:20px 14px}.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.metrics{grid-template-columns:repeat(2,1fr)}.cover,.section{padding:20px}}</style></head><body><main class="page"><section class="cover"><div class="eyebrow">BYERING · LIVE SESSION</div><h1>直播间弹幕分析报告</h1><p class="meta">分析目标：${escapeHtml(text(analysis.goal, "按整场弹幕归纳问题、需求和转化阻力"))}<br>生成时间：${escapeHtml(text(result.generatedAt || analysis.observedAt, "未记录"))}<br>分析方式：${escapeHtml(source)}</p><p class="summary">${escapeHtml(text(analysis.summary, "直播结束后已完成整场用户反馈分析。"))}</p></section><section class="section"><h2>整场数据概览</h2><div class="metrics"><div class="metric"><strong>${metric(counts.danmaku ?? counts.total)}</strong><span>采集弹幕</span></div><div class="metric"><strong>${metric(counts.uniqueUsers)}</strong><span>互动用户</span></div><div class="metric"><strong>${metric(counts.questions)}</strong><span>问题弹幕</span></div><div class="metric"><strong>${metric(userStats.repeatUsers)}</strong><span>重复发言用户</span></div><div class="metric"><strong>${metric(topics.length)}</strong><span>识别主题</span></div></div></section><section class="section"><h2>下一场直播优化策略</h2><p class="summary">${escapeHtml(optimization.headline)}</p><div>${priorityTopics}</div><h3>建议优先执行</h3><ul class="action-list">${nextLiveActions}</ul></section><section class="section"><h2>用户问题与主题</h2><ul>${topicSections}</ul></section><section class="section"><h2>原始弹幕证据</h2><ul class="evidence-list">${evidence}</ul></section><section class="section"><h2>来源与边界</h2><ul><li>本报告在直播结束后，基于本场持续采集到的全部文字弹幕生成。</li><li>本 Agent 负责监听、归纳和提出直播优化建议，不负责私信触达或用户跟进排序。</li><li>优化建议是基于本场用户表达的下一场验证方向，不代表已经证明的因果关系。</li></ul></section></main></body></html>`;
}

